import 'dart:convert';

import 'package:flutter/services.dart';

import 'azkar_catalog.dart';

/// The bundled corpus. `assets/azkar/azkar.json` is generated by
/// `tool/import_azkar.py`; never edit it by hand.
abstract final class AzkarCorpus {
  static const asset = 'packages/academy_islamic/assets/azkar/azkar.json';

  /// Reads the corpus once. An app that ships «Крепость мусульманина» or word
  /// glosses passes those documents in.
  static Future<AzkarCatalog> load(
    AssetBundle bundle, {
    Map<String, dynamic>? hisn,
    Map<String, dynamic>? words,
  }) async => AzkarCatalog.fromJson(
    jsonDecode(await bundle.loadString(asset)) as Map<String, dynamic>,
    hisn: hisn,
    words: words,
  );
}
